import{_ as o,o as e,c as t,a2 as n}from"./chunks/framework.BjkiRu3Q.js";const h=JSON.parse('{"title":"Κρατήσεις μέσω συνομιλίας και συγκατάθεση","description":"","frontmatter":{},"headers":[],"relativePath":"el/integrations/conversational-booking.md","filePath":"el/integrations/conversational-booking.md"}'),i={name:"el/integrations/conversational-booking.md"};function s(r,a,l,c,d,p){return e(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="κρατησεις-μεσω-συνομιλιας-και-συγκαταθεση" tabindex="-1">Κρατήσεις μέσω συνομιλίας και συγκατάθεση <a class="header-anchor" href="#κρατησεις-μεσω-συνομιλιας-και-συγκαταθεση" aria-label="Permalink to &quot;Κρατήσεις μέσω συνομιλίας και συγκατάθεση&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Προσχέδιο βάσει πηγαίου κώδικα · v0.7.9. Επιβεβαιώστε διαθεσιμότητα και δικαιώματα στην εγκεκριμένη έκδοση.</p></div><h2 id="διαδικασια-sandbox" tabindex="-1">Διαδικασία sandbox <a class="header-anchor" href="#διαδικασια-sandbox" aria-label="Permalink to &quot;Διαδικασία sandbox&quot;">​</a></h2><p>Ο κώδικας υποστηρίζει προσομοιώσεις WhatsApp, Meta Messenger και Instagram, στα αγγλικά, ελληνικά, ιταλικά, γαλλικά, γερμανικά και ισπανικά. Αυτό δεν αποδεικνύει ενεργό λογαριασμό εξωτερικών μηνυμάτων.</p><ol><li>Σε εγκεκριμένο sandbox επιλέξτε κανάλι και γλώσσα.</li><li>Δώστε συνθετικό μήνυμα κράτησης, στοιχεία επικοινωνίας και την πραγματική κατάσταση συγκατάθεσης.</li><li>Ελέγξτε τοποθεσίες, αριθμό επιβατών, τύπο υπηρεσίας και προβλήματα επικύρωσης.</li><li>Όταν το αποτέλεσμα είναι έτοιμο, χρησιμοποιήστε <strong>Handoff to Booking Form</strong> και ελέγξτε τα προσυμπληρωμένα πεδία πριν από εγκεκριμένη καταχώριση.</li></ol><h2 id="συγκαταθεση-και-παραπομπη" tabindex="-1">Συγκατάθεση και παραπομπή <a class="header-anchor" href="#συγκαταθεση-και-παραπομπη" aria-label="Permalink to &quot;Συγκατάθεση και παραπομπή&quot;">​</a></h2><p>Το <code>pending_consent</code> είναι η προεπιλογή όταν δεν υπάρχει συγκατάθεση. Το <code>opted_in_transactional</code> δηλώνει ρητή συγκατάθεση για συναλλακτική επικοινωνία. Το <code>opted_out</code> αποκλείει αυτόματη προσφορά. Παραπέμψτε ασαφή αιτήματα σε χειριστή. Μην υποθέτετε συγκατάθεση για προώθηση.</p><p>Το email επιβάτη παραμένει προαιρετικό. Απάντηση sandbox ή αποθηκευμένη συνομιλία δεν αποδεικνύει εξωτερική παράδοση.</p><p>Δείτε <a href="/el/plus/create-reservation.html">Δημιουργία κράτησης</a>.</p>',9)])])}const m=o(i,[["render",s]]);export{h as __pageData,m as default};
